/**
 * Project-type-specific knowledge injected into AI node system prompts and utilities.
 *
 * This is the single source of truth for all framework-specific content.
 * Adding a new framework means adding one entry per exported function here —
 * every node and utility stays clean by importing what it needs.
 *
 * Exported API:
 *   buildConstraints(flags)         — project constraint block for all nodes
 *   buildResearchDirective(type)    — investigation rules for the researcher
 *   buildTddDirective(type)         — TDD section for planner / project manager
 *   buildCoderDirective(type)       — extra instructions for the coder
 *   getBuildCommandRe()             — regex matching framework build commands
 *   UNITY_ASSET_EXTENSIONS          — Set of Unity non-code asset file extensions
 */

// ---------------------------------------------------------------------------
// Constraints — injected into every node's system prompt
// ---------------------------------------------------------------------------

/**
 * Returns the project-type constraint block for all AI nodes.
 * Accepts the flags object produced by detectProjectContext().
 */
export function buildConstraints({ unity, isSwift, isCSharp, isPhp, isNode, isSilverStripe, isGodot }) {
  if (unity)          return UNITY_CONSTRAINTS;
  if (isSwift)        return SWIFT_CONSTRAINTS;
  if (isGodot)        return GODOT_CONSTRAINTS;
  if (isSilverStripe) return SILVERSTRIPE_CONSTRAINTS;
  if (isCSharp)       return CSHARP_CONSTRAINTS;
  if (isPhp)          return PHP_CONSTRAINTS;
  if (isNode)         return NODE_CONSTRAINTS;
  return UNKNOWN_CONSTRAINTS;
}

const UNITY_CONSTRAINTS = `[PROJECT TYPE: Unity C#]
CRITICAL UNITY CONSTRAINTS — MUST FOLLOW:
- ALL C# scripts MUST be placed under Assets/ (typically Assets/Scripts/ or a named feature subfolder). NEVER place scripts in Library/, Temp/, obj/, Packages/, or the project root.
- Do NOT mandate TDD or write test files first. Unity tests require the Unity Test Runner inside the Unity Editor and CANNOT be run from the CLI, dotnet test, or batchmode without a specific test project setup. Only add test subtasks if the original task explicitly requests Edit Mode or Play Mode tests.
- NEVER run "dotnet build" or "dotnet test" on a Unity project. Unity manages its own Roslyn compilation pipeline via the UnityEditor. Running dotnet on a Unity project will fail.
- The Unity project's .sln and .csproj files are AUTO-GENERATED by Unity. Do NOT manually edit them.
- UXML files are XML-based UI layout files. USS files are CSS-like stylesheets. Neither requires C# compilation — write them with correct XML/CSS syntax only.
- C# scripts that use UnityEngine types MUST include "using UnityEngine;" at the top. Editor-only scripts (in an "Editor/" subfolder) MUST include "using UnityEditor;".
- MonoBehaviour subclasses MUST be in a file whose name matches the class name exactly (e.g. PlayerController.cs for class PlayerController).
- Namespaces in C# scripts should match the folder structure under Assets/ to avoid assembly conflicts.
- Assembly Definition (.asmdef) files control which scripts belong to which assembly. If a new script should belong to an existing assembly, place it in the correct folder — do not modify .asmdef files unless specifically required.`;

