const SWIFT_CONSTRAINTS = `[PROJECT TYPE: Swift / Xcode]
CRITICAL SWIFT CONSTRAINTS — MUST FOLLOW:
- Do NOT run "xcodebuild" or "swift build" as a compilation step — the build environment may not have the required signing certificates or SDK configuration. Verify syntax with "swiftc -parse <file>" only.
- Swift files MUST follow the module structure expected by the Xcode project. Do not create new Swift files outside of existing source groups without reading the .xcodeproj or Package.swift first.
- If the project uses Swift Package Manager (Package.swift present), new source files belong under Sources/<TargetName>/. If it is an Xcode project, place files in the appropriate group folder matching the existing structure.
- UIKit apps use UIViewController subclasses and Storyboards/XIBs. SwiftUI apps use View structs. Do not mix paradigms unless the codebase already does so.
- .storyboard and .xib files are XML-based UI layout files. Editing them with write_file is valid; do NOT attempt to compile or validate them beyond checking XML syntax.
- Swift test targets use XCTest. Tests live under <ProjectName>Tests/ (Xcode) or Tests/<TargetName>Tests/ (SPM). Do not run tests from CLI without explicit user request.
- CocoaPods projects have a Podfile and <ProjectName>.xcworkspace. Always open the workspace (not .xcodeproj) when using the Xcode toolchain.
- Do NOT edit files under Pods/ — use the Podfile to manage CocoaPods dependencies.`;

// ---------------------------------------------------------------------------
// Research directive — injected into the researcher system prompt
// ---------------------------------------------------------------------------

/**
 * Returns the researcher investigation directive for the given project type.
 * Injected into the researcher system prompt after the general research rules.
 */
export function buildResearchDirective(projectType) {
  if (projectType === "unity")        return UNITY_RESEARCH_DIRECTIVE;
  if (projectType === "silverstripe") return SILVERSTRIPE_RESEARCH_DIRECTIVE;
  if (projectType === "swift")        return SWIFT_RESEARCH_DIRECTIVE;
  if (projectType === "godot")        return GODOT_RESEARCH_DIRECTIVE;
  return "";
}

