/**
 * Unity UI Toolkit asset files are implementation output, not documentation.
 * They don't require C# compilation but must not be treated as docs-only.
 */
export const UNITY_ASSET_EXTENSIONS = new Set([".uxml", ".uss", ".asmdef", ".asmref"]);

/**
 * Swift/Xcode asset and layout files are implementation output.
 * .storyboard and .xib are XML UI layouts; .xcassets are asset catalog dirs.
 * They don't require Swift compilation but must not be treated as docs-only.
 */
export const SWIFT_ASSET_EXTENSIONS = new Set([".storyboard", ".xib", ".xcassets", ".strings", ".stringsdict"]);
